/* Generated by scripts/build.mjs from assets/app.js — do not edit.
   Same statements, same order, same values; only the comments and the blank lines are
   gone. Edit assets/app.js and rebuild. */
import { FIREBASE_CONFIG, FIREBASE_READY, FIREBASE_SDK, SCHEMA_VERSION } from "./firebase-config.js";
import { createAccountSync, DEVICE_DATA_KEYS, AUTO_PUSH_KEY_PREFIX, FULL_PULL_KEY_PREFIX, num, syncFields } from "./account-sync.js";

const $ = (id) => document.getElementById(id);
const T = (key) => (typeof t === "function" ? t(key) : key);

const state = {
  uid: null, user: null, projects: [], rooms: [], unsub: [],

  fbApp: null,

  profile: null,
  level: LM_LEVEL.GUEST,
};
let db = null, auth = null, fb = null;
let accountSync = null;

let openAccountRoomProjectId = null;

function shareToken() {
  const bytes = crypto.getRandomValues(new Uint8Array(16));
  return btoa(String.fromCharCode(...bytes)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

const newId = () => (crypto.randomUUID ? crypto.randomUUID() : shareToken());

const POPUP_UNAVAILABLE = [
  "auth/popup-blocked",
  "auth/operation-not-supported-in-this-environment",
  "auth/web-storage-unsupported",
];

function authMessage(code) {
  switch (code) {
    case "auth/invalid-email": return T("app_err_email");
    case "auth/weak-password": return T("app_err_password");
    case "auth/email-already-in-use": return T("app_err_inuse");
    case "auth/invalid-credential":
    case "auth/wrong-password":
    case "auth/user-not-found": return T("app_err_credentials");
    case "auth/network-request-failed": return T("app_err_network");
    case "auth/requires-recent-login": return T("app_err_recent_login");
    case "auth/popup-blocked":
    case "auth/popup-closed-by-user":
    case "auth/cancelled-popup-request": return T("app_err_popup");
    case "auth/operation-not-allowed": return T("app_err_provider_off");
    default: return T("app_err_unknown");
  }
}

function status(message, isError) {
  const box = $("app-status");
  if (!box) return;
  box.textContent = message || "";
  box.classList.toggle("err", Boolean(isError));
  box.hidden = !message;
}

const escapeHtml = (s) => String(s)
  .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

async function boot() {
  if (!FIREBASE_READY) {
    $("app-config-missing").hidden = false;
    $("app-auth").hidden = true;
    return;
  }

  const [appMod, authMod, storeMod] = await Promise.all([
    import(`${FIREBASE_SDK}/firebase-app.js`),
    import(`${FIREBASE_SDK}/firebase-auth.js`),
    import(`${FIREBASE_SDK}/firebase-firestore.js`),
  ]);
  fb = { ...authMod, ...storeMod };

  const app = appMod.initializeApp(FIREBASE_CONFIG);
  state.fbApp = app;
  auth = authMod.getAuth(app);
  db = storeMod.getFirestore(app);
  accountSync = createAccountSync({ fb, db, auth, onChange: () => renderLocalSummary() });
  ["workspacechange", "crmchange", "ownmaterialschange"].forEach((name) => {
    document.addEventListener(name, accountSync.armUpSync);
  });

  const followLanguage = () => { auth.languageCode = document.documentElement.lang || "pl"; };
  followLanguage();
  document.addEventListener("langchange", followLanguage);

  try {
    await storeMod.enableIndexedDbPersistence(db);
  } catch (e) {

  }

  authMod.onAuthStateChanged(auth, (user) => (user ? onSignedIn(user) : onSignedOut()));
  wireAuthForms();

  authMod.getRedirectResult(auth).catch((err) => status(authMessage(err && err.code), true));
  wireWorkspace();
  wireTabs();
  wireProfilePanel();
  wireAccountPanel();
  wireSyncPanel();
  wireClientsPanel();
  wireQuotesPanel();
  if (typeof sgMount === "function") sgMount({ prefix: "acctcal", projectUrl: (id) => proLink("projects", id) });
  wireMaterialsPanel();
  wireRoomsPanel();

  renderClients();
  renderQuotes();
  if (typeof sgRender === "function") sgRender("acctcal");
  renderMaterialsPanel();

  if (typeof pwMount === "function") {
    pwMount("acctclients", "clients");
    pwMount("acctquo", "quotes");
    pwMount("acctcal", "calendar");
  }

  document.addEventListener("currencychange", renderPlan);

  window.addEventListener("offline", renderConnection);
  window.addEventListener("online", renderConnection);

  document.addEventListener("langchange", () => {
    renderClients();
    renderQuotes();
    if (typeof sgRender === "function") sgRender("acctcal");
    renderMaterialsPanel();
    if (!state.user) return;
    renderIdentity();
    renderProfile();
    renderPlan();
    renderProjects();
    renderRooms();
    renderLocalSummary();
  });

  document.documentElement.setAttribute("data-app-ready", "1");
}

function showAuthView(view, focus) {
  document.querySelectorAll("[data-auth-view]").forEach((box) => {
    box.hidden = box.dataset.authView !== view;
  });
  const googleBox = $("auth-google-box");
  if (googleBox) googleBox.hidden = view === "reset";
  status("");
  const first = document.querySelector(`[data-auth-view="${view}"] input`);
  if (focus && first) first.focus();
}

async function applyPersistence(remember) {
  lmWriteRemember(remember);
  try {
    await fb.setPersistence(auth, remember ? fb.browserLocalPersistence : fb.browserSessionPersistence);
  } catch (e) {

  }
}

const rememberedIn = (form) => {
  const box = form.querySelector("[data-remember]");
  return box ? box.checked : lmReadRemember();
};

async function submitting(form, run) {
  const button = form.querySelector("button[type=submit]");
  if (button) button.disabled = true;
  status("");
  try {
    await run();
  } catch (err) {
    status(authMessage(err && err.code), true);
  } finally {
    if (button) button.disabled = false;
  }
}

function wireAuthForms() {

  document.querySelectorAll("[data-remember]").forEach((box) => { box.checked = lmReadRemember(); });

  document.querySelectorAll("[data-auth-go]").forEach((button) => {
    button.addEventListener("click", () => showAuthView(button.dataset.authGo, true));
  });

  $("signin-form").addEventListener("submit", (e) => {
    e.preventDefault();
    const form = e.currentTarget;
    submitting(form, async () => {
      await applyPersistence(rememberedIn(form));
      await fb.signInWithEmailAndPassword(auth, $("signin-email").value.trim(), $("signin-password").value);
    });
  });

  $("signup-form").addEventListener("submit", (e) => {
    e.preventDefault();
    const form = e.currentTarget;
    submitting(form, async () => {
      await applyPersistence(rememberedIn(form));
      const cred = await fb.createUserWithEmailAndPassword(
        auth, $("signup-email").value.trim(), $("signup-password").value);

      fb.sendEmailVerification(cred.user).catch(() => {});
    });
  });

  $("reset-form").addEventListener("submit", (e) => {
    e.preventDefault();
    const form = e.currentTarget;
    submitting(form, async () => {
      await fb.sendPasswordResetEmail(auth, $("reset-email").value.trim());
      status(T("app_reset_sent"));
    });
  });

  const googleBtn = $("auth-google");
  if (googleBtn) {
    googleBtn.addEventListener("click", async () => {
      status("");
      const provider = new fb.GoogleAuthProvider();
      try {
        await applyPersistence(lmReadRemember());
        await fb.signInWithPopup(auth, provider);
      } catch (err) {
        const code = err && err.code;

        if (POPUP_UNAVAILABLE.includes(code)) {
          try {
            await fb.signInWithRedirect(auth, provider);
            return;
          } catch (redirectErr) {
            status(authMessage(redirectErr && redirectErr.code), true);
            return;
          }
        }
        status(authMessage(code), true);
      }
    });
  }

  const signOut = async () => {

    stopListening();
    try {
      await fb.signOut(auth);
    } catch (err) {
      status(authMessage(err && err.code), true);
      return;
    }
    status(T("app_signed_out"));
  };
  $("app-signout").addEventListener("click", signOut);
  $("prof-signout").addEventListener("click", signOut);

  showAuthView(lmAuthMode(location.search));
}

const hasPasswordProvider = (user) =>
  (user.providerData || []).some((p) => p.providerId === "password");

async function onSignedIn(user) {
  const uid = user.uid;

  if (state.uid === uid) {
    state.user = user;
    renderIdentity();
    renderProfile();
    return;
  }

  stopListening();

  state.uid = uid;
  accountSync.setUid(uid);
  state.user = user;
  $("app-auth").hidden = true;
  $("app-workspace").hidden = false;
  document.body.classList.add("app-signed-in");

  const password = hasPasswordProvider(user);
  $("password-form").hidden = !password;
  $("email-form").hidden = !password;
  $("app-delete-password-field").hidden = !password;

  const profile = fb.doc(db, "users", uid);
  const now = Date.now();
  try {
    const snap = await fb.getDoc(profile);
    accountSync.requireSyncUid(uid);
    if (snap.exists()) {
      applyProfile(snap.data());
      await fb.updateDoc(profile, { lastSeenAt: now, appVersion: "web" });
      accountSync.requireSyncUid(uid);
    } else {
      applyProfile({ createdAt: now, lastSeenAt: now, appVersion: "web" });
      await fb.setDoc(profile, state.profile);
      accountSync.requireSyncUid(uid);
    }
  } catch (e) {
    if (!accountSync.syncUidActive(uid)) return;

    applyProfile(state.profile);
  }

  if (!accountSync.syncUidActive(uid)) return;

  listenProfile();

  renderIdentity();
  renderProfile();
  renderNext();

  listen("projects", (rows, all) => { state.projects = rows; renderProjects(); accountSync.mirrorToLocal({ projects: all }); });
  listen("rooms", (rows, all) => { state.rooms = rows; renderRooms(); renderProjects(); accountSync.mirrorToLocal({ rooms: all }); });
  renderLocalSummary();

  accountSync.autoReconcile(uid);

  if (accountSync.syncUidActive(uid)) maybeMountAdmin(user);
}

function onSignedOut() {
  stopListening();
  state.uid = null;
  if (accountSync) accountSync.setUid(null);
  state.user = null;
  state.profile = null;
  state.level = LM_LEVEL.GUEST;
  lmWriteLevel(LM_LEVEL.GUEST);
  state.projects = [];
  state.rooms = [];
  $("app-auth").hidden = false;
  $("app-workspace").hidden = true;
  document.body.classList.remove("app-signed-in");
  unmountAdmin();
  showAuthView("signin");
}

function applyProfile(data) {
  state.profile = data || null;
  const level = lmLevelOf(state.user, state.profile);
  const moved = level !== state.level;
  state.level = level;
  lmWriteLevel(level);

  if (moved) renderIdentity();
  renderProfile();
  renderPlan();
}

function listenProfile() {
  const unsub = fb.onSnapshot(
    fb.doc(db, "users", state.uid),
    (snap) => { if (snap.exists()) applyProfile(snap.data()); },
    (err) => {

      if (!state.uid || (err && err.code === "permission-denied")) return;
      status(T("app_err_unknown"), true);
    },
  );
  state.unsub.push(unsub);
}

const displayName = (user) => (user && (user.displayName || user.email)) || "";

function renderIdentity() {
  const user = state.user;
  if (!user) return;
  $("app-who").textContent = displayName(user);
  $("app-level").textContent = T(state.level === LM_LEVEL.PRO ? "acc_pro_t" : "acc_liczmat_t");
  $("app-provider").textContent = hasPasswordProvider(user)
    ? T("app_provider_password") : T("app_provider_google");
  $("app-verified").textContent = user.emailVerified ? T("app_verified") : T("app_unverified");
  $("app-verified").classList.toggle("warn", !user.emailVerified);
  $("app-verify-row").hidden = user.emailVerified;
}

function whenText(millis) {
  if (!millis) return "—";
  const date = new Date(Number(millis));
  if (isNaN(date.getTime())) return "—";
  return new Intl.DateTimeFormat(document.documentElement.lang || "pl",
    { dateStyle: "medium" }).format(date);
}

function renderProfile() {
  const user = state.user;
  if (!user) return;
  const profile = state.profile || {};

  $("prof-email").textContent = user.email || "—";
  $("prof-provider").textContent = hasPasswordProvider(user)
    ? T("app_provider_password") : T("app_provider_google");
  $("prof-created").textContent = whenText(profile.createdAt);
  $("prof-seen").textContent = whenText(profile.lastSeenAt);
  if (document.activeElement !== $("prof-name")) $("prof-name").value = user.displayName || "";

  document.querySelectorAll("#panel-profile [data-levels] .lvl-card").forEach((card) => {
    const here = card.dataset.level === state.level;
    card.toggleAttribute("data-current", here);
    card.querySelector(".lvl-badge").hidden = !here;
  });

  const remember = lmReadRemember();
  $("prof-remember").checked = remember;
  $("prof-session-state").textContent = T(remember ? "prof_session_kept" : "prof_session_tab");
}

function renderPlan() {
  if (!state.user || typeof lmSubscription !== "function") return;
  const sub = lmSubscription(state.user, state.profile);
  const pro = sub.level === LM_LEVEL.PRO;

  const planName = { trial: "plan_trial", free: "plan_free" }[sub.state] || (pro ? "plan_pro" : "plan_free");
  $("plan-name").textContent = T(planName);
  $("plan-name").classList.toggle("warn", sub.state === "expired");

  const dateLabel = {
    active: "plan_renews",
    trial: "plan_trial_until",
    cancelled: "plan_cancelled",
    expired: "plan_until",
  };
  $("plan-until").textContent = sub.validUntil && dateLabel[sub.state]
    ? `${T(dateLabel[sub.state])}: ${whenText(sub.validUntil)}` : "";

  const note = {
    active: "plan_active_d",
    trial: "plan_trial_d",
    cancelled: "plan_cancel_d",
    expired: "plan_expired",
    free: "plan_none",
  }[sub.state] || "plan_none";
  $("plan-note").textContent = T(note);
  $("plan-note").classList.toggle("warn", sub.state === "expired");

  const pending = $("plan-pending");
  if (pending) {
    const waiting = sub.level !== LM_LEVEL.PRO && payPendingActive();
    pending.hidden = !waiting;
    if (!waiting && sub.level === LM_LEVEL.PRO) payPendingClear();
  }

  const portal = typeof lmPortalUrl === "function" ? lmPortalUrl() : null;
  const manage = sub.state === "active" || sub.state === "cancelled";
  $("plan-manage").hidden = !(manage && portal);
  if (manage && portal) $("plan-manage-link").href = portal;

  renderPlanPrices(sub);
}

function renderPlanPrices(sub) {
  const box = $("plan-buy");
  if (!box || typeof lmPayPrice !== "function") return;
  box.hidden = sub.state === "active";

  const code = typeof lmCurrency === "function" ? lmCurrency() : "PLN";
  let chosen = null;
  box.querySelectorAll("[data-pw-plan]").forEach((card) => {
    const id = card.getAttribute("data-pw-plan");
    const minor = lmPayPrice(id, code);
    card.hidden = minor === null;
    if (minor === null) return;
    if (!chosen && lmPayBuyable(id, code)) chosen = id;
    const out = card.querySelector("[data-pw-price]");
    if (out) out.textContent = lmMoneyMinor(minor, code);
  });

  const buy = box.querySelector("[data-pw-buy]");
  const soon = box.querySelector("[data-pw-soon]");
  const btn = box.querySelector("[data-pw-checkout]");
  if (buy) buy.hidden = !chosen;
  if (soon) soon.hidden = Boolean(chosen);
  if (btn) {
    btn.hidden = !chosen;
    btn.textContent = T("pay_buy");
    btn.onclick = chosen ? () => goToCheckout(chosen) : null;
  }
}

var payLeaving = false;

async function goToCheckout(planId) {
  if (payLeaving) return;
  payLeaving = true;
  const url = lmCheckoutUrl(planId, {
    ref: await payTicket(),
    email: state.user && state.user.email,
  });
  if (!url) { payLeaving = false; status(T("pay_soon"), true); return; }
  payPendingSet();
  location.href = url;
}

var PAY_PENDING_KEY = "liczmat-pay-pending";
var PAY_PENDING_MS = 30 * 60 * 1000;

function payPendingSet() {
  try { localStorage.setItem(PAY_PENDING_KEY, String(Date.now())); } catch (e) {   }
}

function payPendingClear() {
  try { localStorage.removeItem(PAY_PENDING_KEY); } catch (e) {   }
}

function payPendingActive(now) {
  let raw = null;
  try { raw = localStorage.getItem(PAY_PENDING_KEY); } catch (e) { return false; }
  const at = Number(raw);
  if (!raw || !Number.isFinite(at)) return false;
  if ((now === undefined ? Date.now() : now) - at > PAY_PENDING_MS) { payPendingClear(); return false; }
  return true;
}

async function payTicket() {
  if (!state.user || !state.fbApp) return null;
  try {
    const { getFunctions, httpsCallable } = await import(`${FIREBASE_SDK}/firebase-functions.js`);

    const res = await httpsCallable(getFunctions(state.fbApp, "europe-central2"), "payTicket")();
    const ticket = res && res.data && res.data.ticket;
    return typeof ticket === "string" && ticket ? ticket : null;
  } catch (e) {
    return null;
  }
}

function renderNext() {
  const next = lmSafeNext(new URLSearchParams(location.search).get("next"));
  if (!next) return;
  $("app-next-link").href = next;
  $("app-next").hidden = false;
}

function wireProfilePanel() {
  $("name-form").addEventListener("submit", (e) => {
    e.preventDefault();
    const form = e.currentTarget;
    submitting(form, async () => {

      await fb.updateProfile(auth.currentUser, { displayName: $("prof-name").value.trim().slice(0, 60) });
      renderIdentity();
      status(T("prof_name_saved"));
    });
  });

  $("prof-remember").addEventListener("change", async (e) => {
    await applyPersistence(e.target.checked);
    document.querySelectorAll("[data-remember]").forEach((box) => { box.checked = e.target.checked; });
    $("prof-session-state").textContent = T(e.target.checked ? "prof_session_kept" : "prof_session_tab");
  });
}

const OFFLINE_AFTER_MS = 10000;

const conn = { synced: new Map(), timer: null, waited: false };

function connectionState() {

  if (!conn.synced.size) return "quiet";

  if (navigator.onLine === false) return "offline";
  for (const synced of conn.synced.values()) if (synced) return "online";
  return "unsynced";
}

function renderConnection() {
  const box = $("app-offline");
  if (!box) return;
  const now = connectionState();

  if (now === "unsynced") {

    if (!conn.waited && !conn.timer) {
      conn.timer = setTimeout(() => {
        conn.timer = null;
        conn.waited = true;
        renderConnection();
      }, OFFLINE_AFTER_MS);
    }
  } else {
    if (conn.timer) clearTimeout(conn.timer);
    conn.timer = null;
    conn.waited = false;
  }

  box.hidden = !(now === "offline" || (now === "unsynced" && conn.waited));
}

function connectionSaw(collectionName, snap) {
  conn.synced.set(collectionName, !snap.metadata.fromCache);
  renderConnection();
}

function listen(collectionName, onRows) {
  const ref = fb.collection(db, "users", state.uid, collectionName);
  let seen = false;
  const unsub = fb.onSnapshot(
    fb.query(ref, fb.orderBy("updatedAt", "desc")),

    { includeMetadataChanges: true },
    (snap) => {
      connectionSaw(collectionName, snap);

      if (!seen || snap.docChanges().length) {
        seen = true;
        const rows = [], all = [];
        snap.forEach((d) => {
          const data = d.data();
          const doc = { id: d.id, ...data };
          all.push(doc);
          if (!data.deletedAt) rows.push(doc);
        });
        accountSync.sawRemote(collectionName, all);
        onRows(rows, all);
      }
    },
    (err) => {

      if (!state.uid || (err && err.code === "permission-denied")) return;
      status(T("app_err_unknown"), true);
    },
  );
  state.unsub.push(unsub);
}

function stopListening() {
  state.unsub.forEach((fn) => fn());
  state.unsub = [];

  if (accountSync) accountSync.clearRemoteStamps();

  conn.synced.clear();
  renderConnection();
}

function wireTabs() {

  const strip = document.querySelector(".app-nav");
  if (!strip) return;
  const tabs = () => Array.from(strip.querySelectorAll(".app-nav-item"));

  const wide = window.matchMedia("(min-width: 900px)");
  const setOrientation = () => strip.setAttribute("aria-orientation", wide.matches ? "vertical" : "horizontal");
  setOrientation();
  wide.addEventListener("change", setOrientation);

  const select = (btn, focus) => {
    if (!btn) return;
    tabs().forEach((b) => {
      const on = b === btn;
      b.setAttribute("aria-selected", String(on));
      b.tabIndex = on ? 0 : -1;
    });

    if (strip.scrollWidth > strip.clientWidth || strip.scrollHeight > strip.clientHeight) {
      btn.scrollIntoView({ inline: "nearest", block: "nearest" });
    }
    document.querySelectorAll("[data-panel]").forEach((panel) => {
      panel.hidden = panel.dataset.panel !== btn.dataset.tab;
    });
    if (focus) btn.focus();
    if (btn.dataset.tab === "overview") renderOverview();
    if (btn.dataset.tab === "clients") renderClients();
    if (btn.dataset.tab === "quotes") renderQuotes();
    if (btn.dataset.tab === "schedule" && typeof sgRender === "function") sgRender("acctcal");
    if (btn.dataset.tab === "materials") renderMaterialsPanel();
    if (btn.dataset.tab === "rooms") renderRoomsPanel();
    if (btn.dataset.tab === "sync") renderLocalSummary();
    if (btn.dataset.tab === "profile") renderProfile();
    if (btn.dataset.tab === "pro") renderPlan();
  };

  strip.addEventListener("click", (e) => {
    const btn = e.target.closest(".app-nav-item");
    if (btn) select(btn);
  });

  strip.addEventListener("keydown", (e) => {
    const btn = e.target.closest(".app-nav-item");
    if (!btn) return;
    const all = tabs();
    const index = all.indexOf(btn);
    const step = e.key === "ArrowRight" || e.key === "ArrowDown" ? 1
      : e.key === "ArrowLeft" || e.key === "ArrowUp" ? -1 : 0;
    if (step) select(all[(index + step + all.length) % all.length], true);
    else if (e.key === "Home") select(all[0], true);
    else if (e.key === "End") select(all[all.length - 1], true);
    else return;
    e.preventDefault();
  });

  document.addEventListener("click", (e) => {
    const goto = e.target.closest("[data-goto-tab]");
    if (!goto) return;
    const target = document.getElementById(`tab-${goto.dataset.gotoTab}`);
    if (target) select(target, true);
  });
}

const ADMIN_CLAIM = "admin";

function unmountAdmin() {
  const tab = document.getElementById("tab-admin");
  const panel = document.getElementById("panel-admin");
  const wasOpen = Boolean(tab) && tab.getAttribute("aria-selected") === "true";
  if (tab) tab.remove();
  if (panel) panel.remove();

  if (wasOpen) {
    const first = document.querySelector(".app-nav .app-nav-item");
    if (first) first.click();
  }
}

async function maybeMountAdmin(user) {
  try {
    const token = await user.getIdTokenResult(true);
    if (!token || !token.claims || token.claims[ADMIN_CLAIM] !== true) return;
    const mod = await import("./admin.js");
    await mod.mountAdmin({ app: state.fbApp });
  } catch (e) {

  }
}

const projectDoc = (id, uid = state.uid) => fb.doc(db, "users", uid, "projects", id);
const roomDoc = (id, uid = state.uid) => fb.doc(db, "users", uid, "rooms", id);

async function addProject(name, fields = {}) {
  const now = Date.now();
  const id = newId();
  const row = {
    name,
    archived: false,
    clientId: fields.clientId || "",
    status: "new",
    dueDate: fields.dueDate || "",
    valueMinor: 0,
    ...syncFields(now),
  };
  await fb.setDoc(projectDoc(id), row);
  return { id, ...row };
}

async function addRoom(name, lengthM, widthM, heightM, projectId) {
  const now = Date.now();
  await fb.setDoc(roomDoc(newId()), {
    name, lengthM, widthM, heightM, projectId: projectId || null, ...syncFields(now),
  });
}

async function tombstone(ref, row, fields) {
  const data = { ...fields, ...syncFields(row.createdAt || Date.now(), Date.now()) };
  accountSync.sawOwnWrite(ref, data.updatedAt);
  await fb.setDoc(ref, data, { merge: true });
}

function renderProjects() {
  fillClientSelect($("project-client"));
  const list = $("project-list");
  if (!state.projects.length) {
    list.innerHTML = `<li class="empty muted">${T("app_empty_projects")}</li>`;
  } else {
    list.innerHTML = state.projects.map((p) => {
      const client = p.clientId && typeof crmClient === "function" ? crmClient(p.clientId) : null;
      const statuses = typeof PROJECT_STATUS !== "undefined" ? PROJECT_STATUS : [p.status || "new"];
      return `<li data-id="${escapeHtml(p.id)}" class="app-project hierarchy-l1">
      <span class="row-name">${escapeHtml(p.name)}${client ? ` <em class="muted">${escapeHtml(client.name)}</em>` : ""}${p.dueDate ? ` <em class="muted">${fmtDay(p.dueDate)}</em>` : ""}${p.archived ? ` <em class="muted">(${T("app_archived")})</em>` : ""}</span>
      <span class="row-actions">
        <select data-status aria-label="${T("job_status")}">${statuses.map((s) => `<option value="${s}"${s === (p.status || "new") ? " selected" : ""}>${T("job_st_" + s)}</option>`).join("")}</select>
        <button type="button" class="btn btn-ghost btn-sm" data-share>${T("app_share")}</button>
        <button type="button" class="btn btn-ghost btn-sm" data-del>${T("app_delete")}</button>
      </span>
      ${roomBlock(p.id)}
    </li>`;
    }).join("");
  }

  renderOverview();
  renderQuotes();
}

const numFmt = (v) => new Intl.NumberFormat(document.documentElement.lang || "pl",
  { maximumFractionDigits: 2 }).format(Number(v) || 0);

const roomRow = (r) => `<li data-id="${escapeHtml(r.id)}">
      <span class="row-name">${escapeHtml(r.name)}
        <em class="muted">${numFmt(r.lengthM)} × ${numFmt(r.widthM)} × ${numFmt(r.heightM)} m — ${T("ws_surface_floor")} ${numFmt(r.lengthM * r.widthM)} m²</em>
      </span>
      <span class="row-actions">
        <button type="button" class="btn btn-ghost btn-sm" data-del>${T("app_delete")}</button>
      </span>
    </li>`;

const looseRoomRow = (r, projects) => `<li data-id="${escapeHtml(r.id)}">
      <span class="row-name">${escapeHtml(r.name)}
        <em class="muted">${numFmt(r.lengthM)} × ${numFmt(r.widthM)} × ${numFmt(r.heightM)} m — ${T("ws_surface_floor")} ${numFmt(r.lengthM * r.widthM)} m²</em>
      </span>
      <span class="row-actions">
        ${projects.length ? `<select data-assign-project aria-label="${T("app_room_assign")}">
          <option value="">${T("app_room_assign_placeholder")}</option>
          ${projects.map((p) => `<option value="${escapeHtml(p.id)}">${escapeHtml(p.name)}</option>`).join("")}
        </select>` : ""}
        <button type="button" class="btn btn-ghost btn-sm" data-del>${T("app_delete")}</button>
      </span>
    </li>`;

function roomBlock(projectId) {
  const rooms = state.rooms.filter((r) => r.projectId === projectId);
  return `<div class="app-rooms hierarchy-l2">
      <ul class="data-list hierarchy-leaves">${
        rooms.length ? rooms.map(roomRow).join("")
          : `<li class="empty muted">${T("app_empty_rooms")}</li>`
      }</ul>
      <form data-room-form class="hierarchy-child-form">${roomFormFields()}
        <p><button type="submit" class="btn btn-ghost btn-sm">${T("app_add_room")}</button></p>
        <p class="muted ws-mat-hint">${T("app_room_hint")}</p>
      </form>
    </div>`;
}

function roomFormFields() {
  return `<p class="ws-mat-grid">
          <label class="ws-mat-f">
            <span class="ws-bar-label">${T("ws_new_room")}</span>
            <input type="text" maxlength="120" data-f="name" placeholder="${T("app_new_room")}" required
              aria-label="${T("app_new_room")}">
          </label>
          <label class="ws-mat-f ws-mat-f-sm">
            <span class="ws-bar-label">${T("fld_length")}</span>
            <input type="text" inputmode="decimal" data-f="lengthM" value="5" aria-label="${T("fld_length")}">
          </label>
          <label class="ws-mat-f ws-mat-f-sm">
            <span class="ws-bar-label">${T("fld_width")}</span>
            <input type="text" inputmode="decimal" data-f="widthM" value="4" aria-label="${T("fld_width")}">
          </label>
          <label class="ws-mat-f ws-mat-f-sm">
            <span class="ws-bar-label">${T("fld_height")}</span>
            <input type="text" inputmode="decimal" data-f="heightM" value="2.6" aria-label="${T("fld_height")}">
          </label>
        </p>`;
}

async function submitRoomForm(form, projectId) {
  const get = (f) => form.querySelector(`[data-f="${f}"]`).value;
  const name = get("name").trim().slice(0, 120);
  if (!name) return false;
  await addRoom(name, Math.min(num(get("lengthM")), 1000),
    Math.min(num(get("widthM")), 1000), Math.min(num(get("heightM")), 100), projectId);
  return true;
}

function renderRooms() {
  const list = $("room-list");
  if (list) {
    const loose = state.rooms.filter((r) => !r.projectId);
    list.innerHTML = loose.length
      ? loose.map(roomRow).join("")
      : `<li class="empty muted">${T("app_rooms_loose_none")}</li>`;
  }
  renderRoomsPanel();
  renderOverview();
}

async function shareProject(project) {
  const sub = (name) => fb.collection(db, "users", state.uid, "projects", project.id, name);
  const [estSnap, shopSnap] = await Promise.all([
    fb.getDocs(sub("estimations")),
    fb.getDocs(sub("shoppingItems")),
  ]);

  const alive = (snap, limit) => {
    const rows = [];
    snap.forEach((d) => { if (!d.data().deletedAt && rows.length < limit) rows.push(d.data()); });
    return rows;
  };
  const estimations = alive(estSnap, 200);
  const shoppingItems = alive(shopSnap, 500);
  const currencyCode = (estimations[0] && estimations[0].currencyCode) || "PLN";

  const token = shareToken();
  const now = Date.now();
  await fb.setDoc(fb.doc(db, "sharedProjects", token), {
    ownerId: state.uid,
    schemaVersion: SCHEMA_VERSION,
    createdAt: now,
    refreshedAt: now,
    projectName: project.name,
    currencyCode,
    estimations,
    shoppingItems,

    creatorLevel: state.level,
  });
  return `${location.origin}/p/${token}`;
}

function wireWorkspace() {
  $("project-form").addEventListener("submit", async (e) => {
    e.preventDefault();
    const input = $("project-name");
    const name = input.value.trim().slice(0, 120);
    if (!name) return;
    const clientId = $("project-client").value;
    const dueDate = $("project-due").value;
    input.value = "";
    $("project-due").value = "";
    try {
      const project = await addProject(name, { clientId, dueDate });
      if (project.clientId && typeof crmLinkProject === "function") crmLinkProject(project.clientId, project.id);
    } catch (err) { status(T("app_err_unknown"), true); }
  });

  $("project-list").addEventListener("submit", async (e) => {
    const form = e.target.closest("[data-room-form]");
    if (!form) return;
    e.preventDefault();
    const li = form.closest("li[data-id]");
    if (!li) return;

    try {
      await submitRoomForm(form, li.dataset.id);
    } catch (err) { status(T("app_err_unknown"), true); }
  });

  $("project-list").addEventListener("click", async (e) => {
    const li = e.target.closest("li[data-id]");
    if (!li) return;
    const project = state.projects.find((p) => p.id === li.dataset.id);

    const roomLi = e.target.closest(".app-rooms li[data-id]");
    if (roomLi && e.target.closest("[data-del]")) {
      const room = state.rooms.find((r) => r.id === roomLi.dataset.id);
      if (room) {
        if (!confirm(T("app_row_delete_confirm"))) return;
        await deleteRoom(room);
        status(T("app_row_deleted"));
      }
      return;
    }
    if (!project) return;

    if (e.target.closest("[data-del]")) {
      const rooms = state.rooms.filter((r) => r.projectId === project.id);
      let question = T("app_project_delete_named").replace("{name}", project.name);
      if (rooms.length) question += ` ${T("app_project_delete_rooms").replace("{count}", rooms.length)}`;
      question += ` ${T("app_project_delete_final")}`;
      if (!confirm(question)) return;
      try {

        await tombstone(projectDoc(project.id), project, { name: project.name, archived: !!project.archived });
        status(T("app_row_deleted"));
      } catch (err) { status(T("app_err_unknown"), true); }
    } else if (e.target.closest("[data-share]")) {
      try {
        const url = await shareProject(project);
        await navigator.clipboard.writeText(url).catch(() => {});
        status(`${T("app_share_copied")}: ${url}`);
      } catch (err) {
        status(T("app_err_unknown"), true);
      }
    }
  });

  $("project-list").addEventListener("change", async (e) => {
    const statusSelect = e.target.closest("[data-status]");
    const li = e.target.closest("li[data-id]");
    if (!statusSelect || !li) return;
    const project = state.projects.find((p) => p.id === li.dataset.id);
    if (!project) return;
    try {
      const updatedAt = Date.now();
      accountSync.sawOwnWrite(projectDoc(project.id), updatedAt);
      await fb.setDoc(projectDoc(project.id), {
        status: statusSelect.value,
        updatedAt,
      }, { merge: true });
    } catch (err) { status(T("app_err_unknown"), true); }
  });

  $("room-list").addEventListener("click", async (e) => {
    const li = e.target.closest("li[data-id]");
    if (!li || !e.target.closest("[data-del]")) return;
    const room = state.rooms.find((r) => r.id === li.dataset.id);
    if (room) {
      if (!confirm(T("app_row_delete_confirm"))) return;
      await deleteRoom(room);
      status(T("app_row_deleted"));
    }
  });
}

const deleteRoom = (room) => tombstone(roomDoc(room.id), room, {
  name: room.name, lengthM: room.lengthM, widthM: room.widthM, heightM: room.heightM,
});

function proLink(routeId, id) {
  const lang = document.documentElement.lang || "pl";
  const nav = window.LM_NAV && window.LM_NAV[routeId];
  const base = (nav && (nav[lang] || nav.pl)) || `/${routeId}/`;
  return `${base}?id=${encodeURIComponent(id)}`;
}

function fmtDay(day) {
  if (!day) return "";
  const d = new Date(`${day}T00:00:00`);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString(document.documentElement.lang || "pl", { day: "numeric", month: "short" });
}

const STAT_ICON = {
  projects: '<path d="M3 7a2 2 0 0 1 2-2h4l2 2.5h8a2 2 0 0 1 2 2V18a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',
  clients: '<circle cx="9" cy="8" r="3.4"/><path d="M2.5 20c0-3.6 2.9-6.2 6.5-6.2s6.5 2.6 6.5 6.2"/><path d="M16.2 4.6a3.4 3.4 0 0 1 0 6.6M20 20c0-3-1.9-5.3-4.6-6"/>',
  schedule: '<rect x="3" y="4.5" width="18" height="16" rx="2"/><path d="M3 9.5h18M8 3v3M16 3v3"/>',
  rooms: '<path d="M4 10 12 3l8 7"/><path d="M6 9v11h12V9"/><path d="M10 20v-6h4v6"/>',
};

function statCard(id, value, label) {
  return `<div class="app-stat-card">
      <svg class="ico" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${STAT_ICON[id] || ""}</svg>
      <div class="app-stat-body"><div class="val">${value}</div><div class="lbl">${label}</div></div>
    </div>`;
}

function renderOverview() {
  const stats = $("overview-stats");
  if (stats) {
    const activeProjects = state.projects.filter((p) => !p.archived);
    const sched = typeof crmSchedule === "function" ? crmSchedule() : null;
    const dueSoon = sched ? sched.counts.late + sched.counts.today + sched.counts.soon : 0;
    const clientsCount = typeof crmClients === "function" ? crmClients().length : 0;
    stats.innerHTML = [
      statCard("projects", activeProjects.length, T("app_stat_projects")),
      statCard("clients", clientsCount, T("app_stat_clients")),
      statCard("schedule", dueSoon, T("app_stat_schedule")),
      statCard("rooms", state.rooms.length, T("app_rooms_title")),
    ].join("");
  }

  const projList = $("overview-projects");
  if (projList) {
    const top = state.projects.filter((p) => !p.archived).slice(0, 5);
    projList.innerHTML = top.length
      ? top.map((p) => `<li><span class="row-name">${escapeHtml(p.name)}</span></li>`).join("")
      : `<li class="empty muted">${T("app_empty_projects")}</li>`;
  }

  const schedList = $("overview-schedule");
  if (schedList) {
    const sched = typeof crmSchedule === "function" ? crmSchedule() : null;
    const items = sched ? [...sched.buckets.late, ...sched.buckets.today, ...sched.buckets.soon].slice(0, 5) : [];
    schedList.innerHTML = items.length
      ? items.map((j) => `<li><span class="row-name">${escapeHtml(j.name)}<em class="muted"> — ${fmtDay(j.dueDate)}</em></span></li>`).join("")
      : `<li class="empty muted">${T("app_schedule_empty_day")}</li>`;
  }

  const matList = $("overview-materials");
  if (matList) {
    const mats = typeof omMaterials === "function" ? omMaterials().slice(0, 5) : [];
    matList.innerHTML = mats.length
      ? mats.map((m) => `<li><span class="row-name">${escapeHtml(m.name)}</span></li>`).join("")
      : `<li class="empty muted">${T("app_materials_empty")}</li>`;
  }
}

function renderClients() {
  const list = $("acctclients-list");
  if (!list || typeof crmClients !== "function") return;
  const rows = crmClients();
  list.innerHTML = rows.length ? rows.map((c) => `<li data-id="${escapeHtml(c.id)}">
      <span class="row-name">${escapeHtml(c.name)}${c.phone ? ` <em class="muted">${escapeHtml(c.phone)}</em>` : ""}</span>
      <span class="row-actions">
        <a class="btn btn-ghost btn-sm btn-go" href="${proLink("clients", c.id)}">${T("app_open_full")}</a>
        <button type="button" class="btn btn-ghost btn-sm" data-del>${T("app_delete")}</button>
      </span>
    </li>`).join("") : `<li class="empty muted">${T("app_clients_empty")}</li>`;
}

function wireClientsPanel() {
  const form = $("acctclients-form");
  if (!form) return;
  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const nameInput = $("acctclients-name");
    const phoneInput = $("acctclients-phone");
    const emailInput = $("acctclients-email");
    const addressInput = $("acctclients-address");
    const name = nameInput ? nameInput.value.trim() : "";
    if (!name || typeof crmAddClient !== "function") return;
    const phone = phoneInput ? phoneInput.value.trim() : "";
    const email = emailInput ? emailInput.value.trim() : "";
    const address = addressInput ? addressInput.value.trim() : "";
    crmAddClient({ name, phone, email, address });
    if (nameInput) nameInput.value = "";
    if (phoneInput) phoneInput.value = "";
    if (emailInput) emailInput.value = "";
    if (addressInput) addressInput.value = "";
    renderClients();
    renderOverview();
  });
  $("acctclients-list").addEventListener("click", (e) => {
    const li = e.target.closest("li[data-id]");
    if (!li || !e.target.closest("[data-del]") || typeof crmDeleteClient !== "function") return;
    if (!confirm(T("app_row_delete_confirm"))) return;
    crmDeleteClient(li.dataset.id);
    renderClients();
    renderProjects();
    renderOverview();
    status(T("app_row_deleted"));
  });
}

function fillClientSelect(select) {
  if (!select || typeof crmClients !== "function") return;
  const rows = crmClients();
  select.innerHTML = `<option value="">${T("app_clients_title")}</option>` +
    rows.map((c) => `<option value="${escapeHtml(c.id)}">${escapeHtml(c.name)}</option>`).join("");
}

const canQuotes = () => typeof lmCan === "function" && lmCan("quotes", state.level);

function renderQuotes() {
  const list = $("acctquo-list");
  if (!list || typeof crmQuotes !== "function") return;

  if (!canQuotes()) { list.innerHTML = ""; return; }
  const projectSelect = $("acctquo-project");
  const activeProjects = state.projects.filter((p) => !p.archived);
  if (projectSelect) {
    const selected = projectSelect.value;
    projectSelect.innerHTML = `<option value="">${T("quo_no_project")}</option>` +
      activeProjects.map((p) => `<option value="${escapeHtml(p.id)}">${escapeHtml(p.name)}</option>`).join("");
    if (activeProjects.some((p) => p.id === selected)) projectSelect.value = selected;
  }
  const noProject = $("acctquo-noproj");
  if (noProject) noProject.hidden = activeProjects.length > 0;
  const rows = crmQuotes();
  list.innerHTML = rows.length ? rows.map((q) => {
    const summary = typeof crmQuoteSummary === "function" ? crmQuoteSummary(q.id) : null;
    if (!summary) return "";

    const meta = [summary.client && summary.client.name, summary.project && summary.project.name]
      .filter(Boolean).map(escapeHtml).join(" · ");
    const changed = T("app_quotes_changed").replace("{date}", whenText(summary.quote.updatedAt));
    const missing = summary.missing.map((part) => T(`quo_missing_${part}`)).join(" · ");
    const total = summary.totals.total === null || typeof wsMoney !== "function" ? "—"
      : wsMoney(summary.totals.total, summary.totals.currencyCode);
    const statuses = typeof QUOTE_STATUS !== "undefined" ? QUOTE_STATUS : [summary.status];
    return `<li data-id="${escapeHtml(q.id)}" class="acctquo-row">
      <span class="acctquo-main">
        <a class="acctquo-name" href="${proLink("quotes", q.id)}">${escapeHtml(q.name)}</a>
        <span class="acctquo-meta muted">${meta ? `${meta} · ` : ""}${escapeHtml(changed)}</span>
        ${missing ? `<span class="acctquo-missing muted">${escapeHtml(missing)}</span>` : ""}
      </span>
      <strong class="acctquo-total">${escapeHtml(total)}</strong>
      <span class="row-actions acctquo-actions">
        <select data-status aria-label="${T("quo_status")}">${statuses.map((s) => `<option value="${s}"${s === summary.status ? " selected" : ""}>${T("quo_st_" + s)}</option>`).join("")}</select>
        <button type="button" class="btn btn-ghost btn-sm" data-del aria-label="${T("app_delete")}: ${escapeHtml(q.name)}">${T("app_delete")}</button>
      </span>
    </li>`;
  }).join("") : `<li class="empty muted"><p>${T("app_quotes_empty")}</p>
      <ol><li>${T("app_quotes_step1")}</li><li>${T("app_quotes_step2")}</li><li>${T("app_quotes_step3")}</li></ol>
    </li>`;
}

function wireQuotesPanel() {
  const form = $("acctquo-form");
  if (!form) return;
  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const nameInput = $("acctquo-name");
    const projectInput = $("acctquo-project");
    const project = state.projects.find((p) => p.id === projectInput.value && !p.archived);
    const name = nameInput.value.trim() || (project && project.name) || "";

    if (typeof crmAddQuote !== "function" || !canQuotes()) return;
    if (!name) {
      status(T("app_quotes_need_name"), true);
      nameInput.focus();
      return;
    }
    const quote = crmAddQuote({ name, projectId: project ? project.id : "" });
    if (quote) location.assign(proLink("quotes", quote.id));
  });
  $("acctquo-list").addEventListener("click", (e) => {
    const li = e.target.closest("li[data-id]");
    if (!li || !e.target.closest("[data-del]") || typeof crmDeleteQuote !== "function"
      || !canQuotes()) return;
    if (!confirm(T("app_row_delete_confirm"))) return;
    crmDeleteQuote(li.dataset.id);
    renderQuotes();
    status(T("app_row_deleted"));
  });
  $("acctquo-list").addEventListener("change", (e) => {
    const select = e.target.closest("[data-status]");
    const li = e.target.closest("li[data-id]");
    if (!select || !li || typeof crmUpdateQuote !== "function" || !canQuotes()) return;
    const id = li.dataset.id;
    crmUpdateQuote(id, { status: select.value });
    renderQuotes();
    const again = [...$("acctquo-list").querySelectorAll("li[data-id]")]
      .find((row) => row.dataset.id === id);
    const next = again && again.querySelector("[data-status]");
    if (next) next.focus();
    status(T("app_quotes_status_saved"));
  });
}

