function renderRoomsPanel() {
  const box = $("acctrooms-list");
  if (!box) return;
  const projects = state.projects.filter((p) => !p.archived);
  const liveIds = new Set(projects.map((p) => p.id));
  const loose = state.rooms.filter((r) => !r.projectId || !liveIds.has(r.projectId));
  const roomColors = ["lime", "blue", "amber", "red", "violet"];
  const groups = projects.map((p, i) => {
    const rooms = state.rooms.filter((r) => r.projectId === p.id);
    const color = roomColors.indexOf(p.color) >= 0 ? p.color : roomColors[i % roomColors.length];
    return `<section class="app-card ws-room-card ws-room-card-${color}" data-project-id="${escapeHtml(p.id)}">
      <div class="ws-room-card-head">
        <h3><span class="ws-room-card-dot" aria-hidden="true"></span>${escapeHtml(p.name)}</h3>
        <span class="chip" data-room-count>${rooms.length}</span>
      </div>
      <ul class="data-list">${rooms.length ? rooms.map(roomRow).join("")
        : `<li class="empty muted">${T("app_empty_rooms")}</li>`}</ul>
      <details class="ws-mat-add" data-room-add${openAccountRoomProjectId === p.id ? " open" : ""}>
        <summary>${T("app_add_room")}</summary>
        <form data-room-form>${roomFormFields()}
          <p><button type="submit" class="btn btn-primary btn-sm">${T("app_add_room")}</button></p>
        </form>
      </details>
    </section>`;
  });
  if (loose.length) {
    groups.push(`<section class="app-card ws-room-card" data-project-id=""><div class="ws-room-card-head">
        <h3>${T("app_rooms_no_project")}</h3><span class="chip" data-room-count>${loose.length}</span>
        </div><ul class="data-list">${loose.map((r) => looseRoomRow(r, projects)).join("")}</ul></section>`);
  }
  box.innerHTML = groups.length ? groups.join("") : `<p class="muted">${T("app_rooms_empty")}</p>`;
  if (openAccountRoomProjectId !== null) {
    const card = [...box.querySelectorAll("[data-project-id]")]
      .find((node) => node.dataset.projectId === openAccountRoomProjectId);
    const name = card && card.querySelector('[data-room-form] [data-f="name"]');
    if (name) name.focus();
    openAccountRoomProjectId = null;
  }
}

function wireRoomsPanel() {
  const box = $("acctrooms-list");
  if (!box) return;
  box.addEventListener("submit", async (e) => {
    const form = e.target.closest("[data-room-form]");
    if (!form) return;
    e.preventDefault();
    const card = form.closest("[data-project-id]");
    if (!card) return;
    openAccountRoomProjectId = card.dataset.projectId;
    try {
      if (!await submitRoomForm(form, card.dataset.projectId)) { openAccountRoomProjectId = null; return; }

      const name = form.isConnected && form.querySelector('[data-f="name"]');
      if (name) { name.value = ""; name.focus(); }
    } catch (err) {
      openAccountRoomProjectId = null;
      status(T("app_err_unknown"), true);
    }
  });
  box.addEventListener("click", async (e) => {
    const li = e.target.closest("li[data-id]");
    if (!li || !e.target.closest("[data-del]")) return;
    const room = state.rooms.find((r) => r.id === li.dataset.id);
    if (room) {
      if (!confirm(T("app_row_delete_confirm"))) return;
      await deleteRoom(room);
      renderRoomsPanel();
      status(T("app_row_deleted"));
    }
  });
  box.addEventListener("change", async (e) => {
    const select = e.target.closest("[data-assign-project]");
    const li = e.target.closest("li[data-id]");
    if (!select || !li || !select.value) return;
    const room = state.rooms.find((r) => r.id === li.dataset.id);
    if (!room) return;
    try {
      const data = { projectId: select.value, ...syncFields(room.createdAt || Date.now()) };
      accountSync.sawOwnWrite(roomDoc(room.id), data.updatedAt);
      await fb.setDoc(roomDoc(room.id), data, { merge: true });
    } catch (err) { status(T("app_err_unknown"), true); }
  });
}

const blockedWorkspace = () => accountSync.blockedWorkspace();

function clearDeviceData() {
  try {
    DEVICE_DATA_KEYS.forEach((key) => localStorage.removeItem(key));
    if (state.uid) {
      localStorage.removeItem(`${AUTO_PUSH_KEY_PREFIX}${state.uid}`);
      localStorage.removeItem(`${FULL_PULL_KEY_PREFIX}${state.uid}`);
    }
    return true;
  } catch (e) { return false; }
}

function renderLocalSummary() {
  const box = $("app-sync-local");
  const counts = accountSync.localCounts();
  if (!box || !counts) return;
  box.textContent = `${T("app_sync_local")}: ${counts.projects} × ${T("app_projects")}, ` +
    `${counts.rooms} × ${T("app_rooms")}, ${counts.estimations} × ${T("ws_lines")}, ` +
    `${counts.shoppingItems} × ${T("proj_mat_t")}`;

  const foreign = accountSync.foreignWorkspace();
  const unclaimed = accountSync.unclaimedWorkspace();
  const warning = $("app-sync-foreign");
  if (warning) {
    warning.textContent = foreign ? T("app_sync_foreign") : "";
    warning.hidden = !foreign;
  }
  const choice = $("app-sync-unclaimed");
  if (choice) choice.hidden = !unclaimed;
  ["app-sync-push", "app-sync-pull"].forEach((id) => {
    const button = $(id);
    if (button) button.disabled = foreign || unclaimed;
  });
}

function wireSyncPanel() {
  const push = $("app-sync-push");
  const pull = $("app-sync-pull");
  if (!push || !pull || typeof wsExport !== "function") return;

  push.addEventListener("click", async () => {

    if (accountSync.blockedWorkspace()) { status(T(accountSync.unclaimedWorkspace() ? "app_sync_unclaimed" : "app_sync_foreign"), true); return; }
    const uid = state.uid;
    push.disabled = true;
    accountSync.state.syncBusy++;
    try {
      accountSync.requireSyncUid(uid);
      if (!accountSync.setSyncAccount(uid)) throw new Error("sync stamp failed");
      await accountSync.syncPushAll(uid);
      renderLocalSummary();
      status(T("app_sync_pushed"));
    } catch (err) {
      status(T("app_err_unknown"), true);
    } finally {
      accountSync.state.syncBusy--;
      renderLocalSummary();
    }
  });

  pull.addEventListener("click", async () => {
    if (accountSync.blockedWorkspace()) { status(T(accountSync.unclaimedWorkspace() ? "app_sync_unclaimed" : "app_sync_foreign"), true); return; }
    const uid = state.uid;
    pull.disabled = true;
    accountSync.state.syncBusy++;
    try {
      const ok = await accountSync.syncPullAll(uid);
      renderLocalSummary();
      if (!ok) { status(T("ws_save_failed"), true); return; }
      if (!accountSync.setSyncAccount(uid)) throw new Error("sync stamp failed");
      status(T("app_sync_pulled"));
    } catch (err) {
      status(T("app_err_unknown"), true);
    } finally {
      accountSync.state.syncBusy--;
      renderLocalSummary();
    }
  });

  $("app-sync-claim-mine").addEventListener("click", async () => {
    const uid = state.uid;
    if (!accountSync.unclaimedWorkspace() || !accountSync.setSyncAccount(uid)) {
      status(T("app_err_unknown"), true);
      return;
    }
    renderLocalSummary();
    await accountSync.autoReconcile(uid);
  });

  $("app-sync-claim-empty").addEventListener("click", async () => {
    const uid = state.uid;

    if (!accountSync.unclaimedWorkspace() || !confirm(T("app_wipe_confirm"))) return;
    if (!clearDeviceData()) {
      status(T("app_err_unknown"), true);
      return;
    }
    renderLocalSummary();
    await accountSync.autoReconcile(uid);
  });
}

const proDoc = (collection, id, uid = state.uid) => fb.doc(db, "users", uid, collection, id);

async function reauthenticate(password) {
  const user = auth.currentUser;
  if (!user) throw Object.assign(new Error("no user"), { code: "auth/user-not-found" });
  if (hasPasswordProvider(user)) {
    const credential = fb.EmailAuthProvider.credential(user.email, password);
    await fb.reauthenticateWithCredential(user, credential);
  } else {
    await fb.reauthenticateWithPopup(user, new fb.GoogleAuthProvider());
  }
}

function wireAccountPanel() {
  $("app-verify-send").addEventListener("click", async () => {
    try {
      await fb.sendEmailVerification(auth.currentUser);
      status(T("app_verify_sent"));
    } catch (err) { status(authMessage(err && err.code), true); }
  });

  $("email-form").addEventListener("submit", async (e) => {
    e.preventDefault();
    try {
      await reauthenticate($("email-password").value);

      await fb.verifyBeforeUpdateEmail(auth.currentUser, $("email-new").value.trim());
      $("email-password").value = "";
      status(T("app_email_changed"));
    } catch (err) { status(authMessage(err && err.code), true); }
  });

  $("password-form").addEventListener("submit", async (e) => {
    e.preventDefault();
    try {
      await reauthenticate($("password-current").value);
      await fb.updatePassword(auth.currentUser, $("password-new").value);
      $("password-current").value = "";
      $("password-new").value = "";
      status(T("app_password_changed"));
    } catch (err) { status(authMessage(err && err.code), true); }
  });

  $("app-wipe").addEventListener("click", () => {
    if (!confirm(T("app_wipe_confirm"))) return;
    if (!clearDeviceData()) {
      status(T("app_err_unknown"), true);
      return;
    }

    document.dispatchEvent(new CustomEvent("workspacechange"));
    renderLocalSummary();
    status(T("app_wipe_done"));
  });

  $("app-export").addEventListener("click", async () => {
    try {
      const uid = state.uid;
      const data = await accountSync.downloadAccount(uid);
      const blob = new Blob([JSON.stringify({ ...data, exportedAt: Date.now(), uid }, null, 2)],
        { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "materio-account.json";
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 1000);
    } catch (err) { status(T("app_err_unknown"), true); }
  });

  $("app-delete-account").addEventListener("click", async () => {
    if (!confirm(T("app_delete_confirm"))) return;
    const button = $("app-delete-account");
    button.disabled = true;
    let stamp = "";
    try {
      await reauthenticate($("delete-password").value);

      stopListening();

      stamp = accountSync.syncAccount();
      accountSync.setSyncAccount("");
      await deleteEverything();
      await fb.deleteUser(auth.currentUser);
      status(T("app_deleted"));
    } catch (err) {
      const code = err && err.code;

      status(code === "permission-denied" ? T("app_err_delete_denied") : authMessage(code), true);
      if (stamp) accountSync.setSyncAccount(stamp);

      if (state.uid) {
        listen("projects", (rows) => { state.projects = rows; renderProjects(); });
        listen("rooms", (rows) => { state.rooms = rows; renderRooms(); renderProjects(); });
        listenProfile();
      }
    } finally {
      button.disabled = false;
    }
  });
}

async function deleteEverything() {
  const del = (ref) => fb.deleteDoc(ref);

  await del(fb.doc(db, "users", state.uid));

  const projSnap = await fb.getDocs(fb.collection(db, "users", state.uid, "projects"));
  for (const project of projSnap.docs) {
    for (const name of ["estimations", "shoppingItems"]) {
      const sub = await fb.getDocs(fb.collection(db, "users", state.uid, "projects", project.id, name));
      for (const d of sub.docs) await del(d.ref);
    }
    await del(project.ref);
  }

  const roomSnap = await fb.getDocs(fb.collection(db, "users", state.uid, "rooms"));
  for (const d of roomSnap.docs) await del(d.ref);

  for (const name of ["clients", "jobs", "quotes", "materials"]) {
    const snap = await fb.getDocs(fb.collection(db, "users", state.uid, name));
    for (const d of snap.docs) await del(d.ref);
  }

  const shared = await fb.getDocs(
    fb.query(fb.collection(db, "sharedProjects"), fb.where("ownerId", "==", state.uid)));
  for (const d of shared.docs) await del(d.ref);
}

document.addEventListener("DOMContentLoaded", () => {
  boot().catch((err) => {

    console.error("LiczMat /app/ did not finish starting:", err);
    status(T("app_err_unknown"), true);
  });
});
